import {units,subjects,subjectById,unitById} from './curriculum.js';
import {knowledgePoints,teachingFor} from './teaching.js';
import {supplements} from './supplements.js';
import {reviewedQuestions} from './cap-reviewed.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const grades={7:'國一',8:'國二',9:'國三'};
const statuses={covered:'已有教學對應',partial:'部分涵蓋・待補強',pending:'尚待逐題核對'};
const subjectNames={...Object.fromEntries(subjects.map(s=>[s.id,s.name])),social:'社會',science:'自然',writing:'寫作',listening:'英語聽力',answers:'參考答案',notes:'試題說明'};
const safeLink=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
const links=ids=>ids.map(id=>`<a href="#/lesson/${id}">${esc(unitById[id]?.title||id)}</a>`).join('、');
const heading=(title,lead)=>`<div class="eyebrow">CURRICULUM · EVIDENCE · REVIEW</div><h1>${title}</h1><p class="intro muted">${lead}</p><div class="actions"><a class="button secondary" href="#/library">六學期講義</a><a class="button secondary" href="#/alignment">版本與課綱對照</a><a class="button secondary" href="#/pastpapers">近七年會考題庫</a><a class="button secondary" href="#/gsat">學測歷屆模考</a></div>`;
let cached;
async function data(){if(!cached)cached=Promise.all(['alignment-data.json','cap-manifest.json','handouts-manifest.json'].map(async path=>{const r=await fetch(new URL(path,import.meta.url));if(!r.ok)throw new Error('資料載入失敗');return r.json()})).catch(e=>{cached=null;throw e});return cached;}
async function load(main,route,draw){main.innerHTML=heading('正在載入學習資料','整理課程、講義與來源…');try{const d=await data();if(location.hash.split('?')[0]!==route)return;draw(d)}catch{if(location.hash.split('?')[0]!==route)return;main.innerHTML='<section class="panel"><h1>資料暫時無法載入</h1><p>請確認連線後重試。</p><button class="button" id="retry-library">重試</button></section>';main.querySelector('button').onclick=()=>load(main,route,draw)}}
export function lessonResources(u){const points=knowledgePoints(u).length+teachingFor(u).rows.length+(supplements[u.id]?.points.length||0),reviewed=reviewedQuestions.filter(q=>q.unitIds.includes(u.id));return `<section class="panel lesson-resources"><h2>複習講義與知識點索引</h2><p>本課整理 ${points} 項教學條目（概念、表格與補充；不等同官方獨立指標數）。</p><div class="actions"><a class="button" download href="./downloads/handouts/${u.id}.pdf">下載本章 PDF 複習講義</a><a class="button secondary" href="#/library">依年級・學期・科目找講義</a></div>${reviewed.length?`<h3>已初核的歷屆題目關聯</h3><ul>${reviewed.map(q=>`<li><a href="#/pastpapers?year=115&subject=math">115 年數學 ${esc(q.id.replace('115-math-','').replace('written-','非選 '))} 題</a>：${statuses[q.status]}。${esc(q.evidence)}</li>`).join('')}</ul>`:'<p class="subtle">本課與七年真題的逐題對照尚未完成；請勿把下載題本視為已驗證教學涵蓋。</p>'}</section>`;}
export function libraryPage(main,grade='all'){
 load(main,'#/library',([alignment,cap,handouts])=>{
  let selected='all',term='all',query='';
  const draw=()=>{
   const files=handouts.files.filter(f=>(grade==='all'||f.grade===Number(grade))&&(selected==='all'||f.subject===selected)&&(term==='all'||f.term===Number(term))&&(!query||[f.title,subjectById[f.subject].name].join(' ').includes(query)));
   main.innerHTML=heading('國一到國三・六學期複習講義','選年級、學期與科目，從章節整理回到完整教學。講義包含圖表、示範、練習和解答。')+`<div class="panel"><p class="notice">${handouts.files.length} 份現有單元講義已可下載。下方依本站建議進度排列；版本實際章節請看「版本與課綱對照」。空白學期表示本站尚無該科單元，不能解讀成該學期不用學。</p><div class="filters"><label>科目 <select id="library-subject"><option value="all">全部科目</option>${subjects.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${s.name}</option>`).join('')}</select></label><label>學期 <select id="library-term"><option value="all">上下學期</option><option value="1" ${term==='1'?'selected':''}>上學期</option><option value="2" ${term==='2'?'selected':''}>下學期</option></select></label><label>搜尋 <input id="library-query" type="search" value="${esc(query)}" placeholder="章節或科目"></label><span>${files.length} 份</span></div><a class="button secondary" download href="./downloads/handouts-all.zip">下載全部講義 ZIP</a></div>`+[7,8,9].filter(g=>grade==='all'||g===Number(grade)).flatMap(g=>[1,2].filter(t=>term==='all'||t===Number(term)).map(t=>{const semester=files.filter(f=>f.grade===g&&f.term===t);return `<section class="panel"><h2>${grades[g]}・${t===1?'上':'下'}學期 <span class="tag">${semester.length} 章</span></h2>${semester.length?subjects.filter(s=>semester.some(f=>f.subject===s.id)).map(s=>`<details class="semester-subject" ${selected!=='all'?'open':''}><summary>${s.name} · ${semester.filter(f=>f.subject===s.id).length} 章</summary><ul class="download-list">${semester.filter(f=>f.subject===s.id).map(f=>`<li><a href="#/lesson/${f.unitId}">${esc(f.title)}</a><a class="button small secondary" href="./${f.path}" download aria-label="下載${esc(f.title)} PDF">PDF ↓</a></li>`).join('')}</ul></details>`).join(''):'<p>目前沒有符合條件的講義。</p>'}</section>`})).join('');
   main.querySelector('#library-subject').onchange=e=>{selected=e.target.value;draw()};main.querySelector('#library-term').onchange=e=>{term=e.target.value;draw()};main.querySelector('#library-query').oninput=e=>{query=e.target.value;const p=e.target.selectionStart;draw();const input=main.querySelector('#library-query');input.focus();input.setSelectionRange(p,p)};
  };draw();
 });
}
export function alignmentPage(main,grade='all'){
 load(main,'#/alignment',([alignment])=>{
  let subject='math',publisher='康軒';
  const draw=()=>{
   const books=alignment.books.filter(b=>(b.subject===subject||b.subjectIds?.includes(subject))&&(grade==='all'||b.grade===Number(grade))&&b.publisher===publisher);
   main.innerHTML=heading('版本章節與課綱對照','保留出版社、學年度、冊別與來源，逐章檢查教學缺口。')+`<div class="panel"><div class="filters"><label>科目 <select id="align-subject">${subjects.map(s=>`<option value="${s.id}" ${s.id===subject?'selected':''}>${s.name}</option>`).join('')}</select></label><label>版本 <select id="align-publisher">${['康軒','翰林','南一'].map(p=>`<option ${p===publisher?'selected':''}>${p}</option>`).join('')}</select></label></div><p class="notice">康軒來源為 115 學年度出版社公開計畫；翰林、南一補充來源為學校公開的 115 上／114 下計畫，不能視為同一學年度完整六冊。課綱代碼與章節已建索引，完整知識點覆蓋仍待核對。相關課程連結僅為主題關聯。</p><p>${safeLink('https://www.naer.edu.tw/PageSyllabus?fid=52','官方課綱原文')} · ${safeLink('https://www.knsh.com.tw/service/plan','康軒課程計畫')} · <a href="./alignment-data.json" download>下載對照資料 JSON</a></p></div>`+[7,8,9].filter(g=>grade==='all'||g===Number(grade)).flatMap(g=>[1,2].map(t=>{const found=books.filter(b=>b.grade===g&&b.term===t);return `<section class="panel"><h2>${grades[g]}・${t===1?'上':'下'}學期</h2>${found.length?found.map(b=>`<p><span class="tag">${b.publisher} ${b.schoolYear} 學年度</span> ${safeLink(b.sourceUrl,'查看原始課程計畫')}<br><small>${esc(b.sourceKind)}</small></p>${b.chapters.length?`<div class="table-wrap"><table class="teaching-table"><caption>${esc(subjectNames[subject])}版本章節清單</caption><thead><tr><th>章節／課次</th><th>課綱代碼</th><th>本站相關教學</th><th>核對狀態</th></tr></thead><tbody>${b.chapters.map(c=>`<tr><th scope="row">${esc(c.chapter)}<br>${esc(c.lesson)}</th><td>${c.codes.map(esc).join('、')||'待核對'}</td><td>${c.unitIds.length?links(c.unitIds):'尚待建立對應'}</td><td>待逐點核對</td></tr>`).join('')}</tbody></table></div>`:'<p>已取得來源；章節與課綱代碼尚待整理，請先查看原始計畫。</p>'}`).join(''):'<p class="notice">尚未取得此版本、科目與學期的可靠章節資料；未以其他版本推填。</p>'}</section>`})).join('');
   main.querySelector('#align-subject').onchange=e=>{subject=e.target.value;draw()};main.querySelector('#align-publisher').onchange=e=>{publisher=e.target.value;draw()};
  };draw();
 });
}
export function pastpapersPage(main){
 load(main,'#/pastpapers',([alignment,cap])=>{
  const params=new URLSearchParams(location.hash.split('?')[1]||'');let year=cap.years.includes(Number(params.get('year')))?Number(params.get('year')):115,subject=['chinese','english','math','social','science','writing','listening'].includes(params.get('subject'))?params.get('subject'):'math',status='all';
  const reviewed=Object.fromEntries(reviewedQuestions.map(q=>[q.id,q]));const rows=alignment.questions.map(q=>({...q,...reviewed[q.id]}));
  const draw=()=>{
   const selected=rows.filter(q=>q.year===year&&q.subject===subject),shown=selected.filter(q=>status==='all'||q.status===status),files=cap.files.filter(f=>f.year===year),downloaded=cap.files.filter(f=>f.status==='downloaded').length;
   main.innerHTML=heading('109–115 年・官方會考題庫','2020–2026 年正式試題、參考答案與教學知識點對照。')+`<div class="panel"><p>${downloaded} 份官方索引檔案已下載；來源與 SHA-256 校驗紀錄可查。</p><p class="notice">題本下載與教學覆蓋是兩件不同的事。已匯入 ${alignment.summary.officialObjectives||0} 題官方評量目標與命題依據；目前 ${reviewedQuestions.length} 題完成本站教學內容初核，其餘仍待檢查。109、110 年試題屬課綱銜接前資料，需另外檢視與現行課綱差異；109 年官方未施測英聽。111–115 年英聽已依官方分析逐題建檔；110 年英聽尚待建檔。未經外部教師複核。</p><div class="filters"><label>年度 <select id="cap-year">${[...cap.years].reverse().map(y=>`<option value="${y}" ${year===y?'selected':''}>${y} 年（${y+1911}）</option>`).join('')}</select></label><label>科目 <select id="cap-subject">${['chinese','english','math','social','science','writing','listening'].map(s=>`<option value="${s}" ${subject===s?'selected':''}>${subjectNames[s]}</option>`).join('')}</select></label><label>對照狀態 <select id="cap-status"><option value="all">全部</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="actions">${files.filter(f=>[subject,'answers','notes'].includes(f.subject)).map(f=>f.status==='downloaded'?`<a class="button ${f.subject===subject?'':'secondary'}" href="./${f.path}" download>下載${esc(f.label)} ${f.path.endsWith('.zip')?'ZIP':'PDF'}</a>`:`<span>${esc(f.label)}下載失敗：${safeLink(f.sourceUrl,'官方來源')}</span>`).join('')}</div>${subject==='listening'&&year===109?'<p>109 年未施測英語聽力，無題本可下載。</p>':''}<p>${safeLink(`https://cap.rcpet.edu.tw/exam/${year}/${year}exam.html`,'本年度官方索引')} · <a href="./cap-manifest.json" download>下載檔案校驗紀錄</a></p></div><div class="panel"><h2>題目需要什麼？教學補到哪裡？</h2><p>本卷 ${selected.length} 項：已有教學對應 ${selected.filter(q=>q.status==='covered').length}、部分涵蓋 ${selected.filter(q=>q.status==='partial').length}、待核對 ${selected.filter(q=>q.status==='pending').length}。</p>${shown.length?`<div class="table-wrap"><table class="teaching-table"><caption>${year} 年 ${subjectNames[subject]}逐題對照</caption><thead><tr><th>題號／原題</th><th>所需知識</th><th>教學與判讀依據</th><th>狀態</th></tr></thead><tbody>${shown.map(q=>`<tr><th scope="row"><a href="./${q.sourcePath}${q.page?'#page='+q.page:''}" target="_blank" rel="noopener">${esc(q.number)} 題 ↗</a>${q.page?`<small class="block">PDF 第 ${q.page} 頁</small>`:''}</th><td>${q.officialObjective?`<strong>官方評量目標</strong><p>${esc(q.officialObjective)}</p><small>${q.officialCodes.map(esc).join('、')}</small><p><a href="./${q.analysisPath}#page=${q.analysisPage}" target="_blank" rel="noopener">官方分析第 ${q.analysisPage} 頁 ↗</a></p>`:''}${q.required.length?`<p>教學拆解：${q.required.map(esc).join('、')}</p>`:q.officialObjective?'':'尚待人工辨識（含圖表與題組）'}</td><td>${links(q.unitIds)}${!q.unitIds.length&&q.candidateUnitIds?.length?`<p>待確認的相關主題：${links(q.candidateUnitIds)}</p>`:''}<p>${esc(q.evidence)||'不以關鍵字命中代替完整教學驗證。'}</p></td><td><span class="tag ${q.status==='covered'?'success':''}">${statuses[q.status]}</span></td></tr>`).join('')}</tbody></table></div>`:'<p>此篩選下沒有已建檔的逐題對照。可下載官方題本先行練習。</p>'}</div>`;
   main.querySelector('#cap-year').onchange=e=>{year=Number(e.target.value);draw()};main.querySelector('#cap-subject').onchange=e=>{subject=e.target.value;draw()};main.querySelector('#cap-status').onchange=e=>{status=e.target.value;draw()};
  };draw();
 });
}
